import ast

user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error: {e}')

# Check for for loop
found_loop = False
loop_variable = None
for node in ast.walk(tree):
    if isinstance(node, ast.For):
        found_loop = True
        # Get the loop variable name(s)
        if isinstance(node.target, ast.Name):
            loop_variable = node.target.id
        elif isinstance(node.target, ast.Tuple):
            # If they're unpacking like for name, price in all_products
            loop_variable = [elt.id for elt in node.target.elts if isinstance(elt, ast.Name)]
        break

if not found_loop:
    raise AssertionError('Task 3: Missing for loop')

# Check for print statement inside loop
found_print_in_loop = False
print_args = None
for node in ast.walk(tree):
    if isinstance(node, ast.For):
        for child in ast.walk(node):
            if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == 'print':
                found_print_in_loop = True
                # Get the print arguments to check what's being printed
                if child.args:
                    print_args = child.args
                break

if not found_print_in_loop:
    raise AssertionError('Task 3: Missing print statement inside for loop')

# Check that the print statement references either tuple indexing or the loop variables
if print_args:
    print_str = ast.unparse(print_args[0])

    # Case 1: Using tuple indexing like product[0] and product[1]
    if 'product[0]' in print_str and 'product[1]' in print_str:
        pass  # This is valid

    # Case 2: Using unpacked variables like name and price
    elif loop_variable and isinstance(loop_variable, list) and len(loop_variable) == 2:
        if loop_variable[0] in print_str and loop_variable[1] in print_str:
            pass  # This is valid (unpacking)
        else:
            raise AssertionError(f'Task 3: Your print statement should use your unpacked variables {loop_variable[0]} and {loop_variable[1]}')

    # Case 3: They used undefined variables (like name, price without unpacking)
    elif 'name' in print_str and 'price' in print_str:
        raise AssertionError('Task 3: You used "name" and "price" directly, but these variables don\'t exist. Either use tuple indexing (product[0], product[1]) or unpack the tuple in the loop header (for name, price in all_products).')

    else:
        # Check if they're using any valid approach we might have missed
        has_index_access = any(f'[{i}]' in print_str for i in range(2))
        if not has_index_access:
            raise AssertionError('Task 3: Your print statement should reference the tuple elements using either indexing (product[0], product[1]) or unpacked variables.')

print('TEST_PASSED')
